public class Bfs {
    static void bfs(Map<Integer, List<Integer>> g, int s) {
        Deque<Integer> d = new ArrayDeque<>();
        d.add(s);
        while (!d.isEmpty()) {
            int u = d.pollLast();
            for (int v : g.getOrDefault(u, List.of())) d.add(v);
        }
    }
}

